#!/usr/bin/env python3
import argparse,html,json,re,shutil,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
TIMES=[(0,3),(3,6),(6,9),(9,12),(12,15),(15,18),(18,21),(21,24),(24,27),(27,30),(30.5,34),(34,38),(38,42),(42,46),(46,50),(50,54),(54,58),(58,62),(62,66),(66,70),(70,74),(74,78),(78,82),(82,86),(86,90)]
VISUALS=['粒子人海的漩涡，两颗冷暖光点分开行进','人海保持流动，关系未形成','消息轨迹逐步伸出后撤回','两个分离的粒子环，距离可见','密集粒子化为潮汐波面','两束粒子向不同方向流动','透视路径网，光点在不同道路前进','粒子变成冷暖双螺旋，在空间交错','两束流光靠近，但留有缺口','双光点沿同一光环接近，蓄力收暗','锚词当帧落下，冲击环扩散，粒子聚字','左侧事实与来源，右侧网络逐步连线','三个联系群组与主题标签','回到透视路径网，表现生活范围','外围人群减弱，近处范围显现','粒子轨迹分岔，呈现尚未到达的方向','粒子逐步排成打开的书页','两个光点进入交叠的轨道','铜橙轨迹发出，冰蓝光点停留等待','冰蓝轨迹从另一端返回','两种不同节奏继续存在','回应向发出者到达','两条不同路径继续向前','锚词温和回归，两光点靠近','光点相互停留，随末乐句收束']
p=argparse.ArgumentParser();p.add_argument('--story',required=True);p.add_argument('--out',required=True);args=p.parse_args();s=json.loads(Path(args.story).read_text());out=Path(args.out).resolve();out.mkdir(parents=True,exist_ok=True);(out/'assets').mkdir(exist_ok=True)
assert 2<=len(s['anchor'])<=4,'Anchor must be 2–4 Chinese characters'
assert len(s['captions'])==25,'Exactly 25 fixed-timing captions required'
assert len(s['cover_lines'])==2
for line in s['captions']:
 assert len(re.findall(r'[\u4e00-\u9fff]',line['cn']))<=18,line['cn']
 assert len(line['en'])<=110,line['en']
for x in s['cover_lines']:assert len(x)<=18,x
assert len(s['cluster_labels'])==3
shutil.copytree(ROOT/'assets/fonts',out/'assets/fonts',dirs_exist_ok=True);shutil.copy2(ROOT/'assets/fonts.css',out/'assets/fonts.css')
(out/'story.json').write_text(json.dumps(s,ensure_ascii=False,indent=2))
shutil.copy2(ROOT/'templates/engine.js',out/'art.js');shutil.copy2(ROOT/'assets/gsap.min.js',out/'assets/gsap.min.js');shutil.copy2(ROOT/'references/style-and-timing.md',out/'DESIGN.md')
(out/'config.js').write_text('const FILM_CONFIG='+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+';')
(out/'glyph.js').write_text('window.GLYPH=null;')
e=html.escape;font=min(274,int(590/len(s['anchor'])))
css='''*{box-sizing:border-box}html,body{margin:0;width:1920px;height:1080px;overflow:hidden;background:#070b13;color:#f9f1df;font-variant-numeric:lining-nums tabular-nums;font-feature-settings:"lnum" 1,"tnum" 1}#film{position:relative;width:1920px;height:1080px;background:#070b13;overflow:hidden}canvas{position:absolute;inset:0;width:1920px;height:1080px}.caption{position:absolute;left:100px;right:100px;top:892px;text-align:center;z-index:3}.cn{font:400 42px/1.45 "Noto Serif CJK SC";letter-spacing:2px;text-shadow:0 2px 16px #000}.en{font:italic 28px/1.55 "Liberation Serif";letter-spacing:.5px;color:#b9c9da;margin-top:7px;text-shadow:0 2px 14px #000}#hero{position:absolute;left:0;top:257px;width:1920px;text-align:center;z-index:2;opacity:0}#hero .word{font:700 FONTpx/1.45 "Noto Serif CJK SC";letter-spacing:32px;color:#fff5e7;text-shadow:0 0 16px #ffb68b88,0 0 58px #68b8ff33}#hero .term{font:26px "Noto Serif CJK SC";letter-spacing:4px;color:#c0d4e5;margin-top:14px}#cover{position:absolute;inset:0;z-index:4;display:flex;flex-direction:column;justify-content:center;align-items:center;padding:140px 100px 180px;text-align:center;gap:16px}#cover .kicker{font:30px "Noto Serif CJK SC";letter-spacing:10px;color:#89ceff;margin-bottom:20px}#cover .question{font:700 88px/1.4 "Noto Serif CJK SC";letter-spacing:3px;text-shadow:0 0 30px #03050a}#cover .question.second{font-size:110px;color:#ffb38c}#cover .cover-en{font:italic 29px "Liberation Serif";color:#c0d4e5;margin-top:24px}#fact{position:absolute;left:165px;top:290px;width:640px;z-index:2;opacity:0;text-align:left}#fact .number{font:124px/1.2 "Liberation Sans";color:#ffb38c;margin-bottom:28px}#fact .heading{font:30px/1.6 "Noto Serif CJK SC";margin-bottom:20px}#fact .authors,#fact .source{font:24px/1.6 "Liberation Sans";color:#c0d4e5}#labels{position:absolute;left:280px;right:280px;top:752px;display:flex;justify-content:space-around;font:30px "Noto Serif CJK SC";color:#dfecf4;z-index:2;opacity:0}#end-anchor{position:absolute;left:0;top:280px;width:1920px;text-align:center;font:700 156px/1.5 "Noto Serif CJK SC";letter-spacing:24px;color:#fff5e7;text-shadow:0 0 26px #89ceff33;z-index:2;opacity:0}#veil,#out{position:absolute;inset:0;background:#03050a;opacity:0;z-index:9}#out{z-index:10}'''.replace('FONT',str(font))
h='<html><head><meta charset="utf-8"><link rel="stylesheet" href="assets/fonts.css"><title>'+e(s['anchor'])+'</title><style>'+css+'</style></head><body><div id="film" data-composition-id="film" data-start="0" data-duration="93" data-width="1920" data-height="1080"><canvas id="art" width="1920" height="1080" data-layout-ignore></canvas>'
h+='<div id="cover"><div class="kicker">'+e(s['anchor'])+'</div><div class="question">'+e(s['cover_lines'][0])+'</div><div class="question second">'+e(s['cover_lines'][1])+'</div><div class="cover-en">'+e(s['cover_en'])+'</div></div>'
for i,x in enumerate(s['captions']):h+=f'<div class="caption" id="c{i}"><div class="cn">{e(x["cn"])}</div><div class="en">{e(x["en"])}</div></div>'
h+='<div id="hero"><div class="word">'+e(s['anchor'])+'</div><div class="term">'+e(s['term_cn'])+' · '+e(s['term_en'])+'</div></div>'
f=s['fact'];h+='<div id="fact">'+''.join('<div class="'+k+'">'+e(str(f.get(k,'')))+'</div>'for k in ['number','heading','authors','source'])+'</div>'
h+='<div id="labels">'+''.join('<span>'+e(x)+'</span>'for x in s['cluster_labels'])+'</div><div id="end-anchor">'+e(s['anchor'])+'</div><div id="veil"></div><div id="out"></div><audio id="audio" src="assets/mix.wav" data-start="3" data-duration="90" data-track-index="2" data-volume="1"></audio></div><script src="assets/gsap.min.js"></script><script src="config.js"></script><script src="glyph.js"></script><script src="art.js"></script><script>'
h+='const captionTimes='+json.dumps(TIMES)+';'+'''const tl=gsap.timeline({paused:true});tl.to('#cover',{opacity:0,duration:.45,ease:'sine.in'},2.55);captionTimes.forEach(([a,b],i)=>{tl.from('#c'+i,{opacity:0,y:7,duration:.30,ease:'sine.out',immediateRender:true},a+3.10);tl.to('#c'+i,{opacity:0,duration:.16,ease:'sine.in'},b+3-.16)});tl.to('#veil',{opacity:1,duration:.4,ease:'sine.inOut'},33);tl.set('#veil',{opacity:0},33.5);tl.set('#hero',{opacity:1},33.5);tl.from('#hero .word',{scale:1.065,duration:.2,ease:'power3.out'},33.5);tl.from('#hero .term',{opacity:0,duration:.30,ease:'sine.out'},33.6);tl.to('#hero',{opacity:0,duration:.3,ease:'sine.in'},36.7);tl.to('#fact',{opacity:1,duration:.5,ease:'power1.out'},37.25);tl.to('#fact',{opacity:0,duration:.25,ease:'sine.in'},40.75);tl.to('#labels',{opacity:1,duration:.5,ease:'sine.out'},41.45);tl.to('#labels',{opacity:0,duration:.25,ease:'sine.in'},44.75);tl.to('#end-anchor',{opacity:1,duration:1.3,ease:'sine.out'},85.2);tl.to('#out',{opacity:1,duration:1.3,ease:'sine.inOut'},91.7);tl.eventCallback('onUpdate',()=>drawFilm(tl.time()));window.__timelines={film:tl};window.seek=t=>{tl.time(t,false);drawFilm(t)};window.seek(0);</script></body></html>'''
(out/'index.html').write_text('<!doctype html>'+h)
rows=['# '+s['theme'],'','锚词：'+s['anchor']+'。位置（成片时间）：0–3秒封面小题、30–33秒发问字幕、33.5–37秒高潮巨字、85.2–93秒片尾巨字；85–89秒字幕再次定义。封面之后的时间减3秒即正片时间。','','|段落|正片时间|成片时间|画面|转场|中文|英文|声音|','|---|---|---|---|---|---|---|---|','|封面|—|0–3|完整主题问题＋同画风粒子|题字淡出，粒子连续|'+s['theme']+'|'+s['cover_en']+'|静音|']
for i,((a,b),x) in enumerate(zip(TIMES,s['captions'])):rows.append(f'|{i+1}|{a}–{b}|{a+3}–{b+3}|{VISUALS[i]}|'+('收暗、3帧静止、巨字当帧落下'if i==10 else'同一批粒子连续重排')+f'|{x["cn"]}|{x["en"]}|'+('低沉冲击'if i==10 else'固定音乐与轻环境音')+'|')
rows+=['','音效时间（成片）：9.13秒轻掠过、15.12秒气流、24.12秒转场、33.50秒低沉冲击、37.15秒信息揭示、57.22秒清亮落点、77.20秒回应、90.60秒片尾。']
(out/'storyboard.md').write_text('\n'.join(rows));subprocess.run([sys.executable,str(ROOT/'scripts/audio.py'),'--source',str(ROOT/'assets/we-never.m4a'),'--output',str(out/'assets/mix.wav')],check=True);print('BUILT',out)
